import type { Metadata } from 'next';
import Link from 'next/link';
import { changes, commitUrl, formatDate, CONTRACT_HISTORY } from '@/lib/resources';
import { endpoint, endpointHref } from '@/lib/docs';
import { DocPage } from '@/components/DocPage';
import { Icon } from '@/components/Icon';

export const metadata: Metadata = { title: 'API changelog', description: 'Every change to the USAspending API contracts, linked to the endpoints it touched.' };

const monthName = (ym: string) => new Date(`${ym}-15T12:00:00Z`).toLocaleDateString('en-US', { month: 'long', year: 'numeric', timeZone: 'UTC' });

export default function Changelog() {
  const months = [...new Set(changes.map((c) => c.date.slice(0, 7)))];
  const touched = new Set(changes.flatMap((c) => c.endpoints));
  const newEps = changes.flatMap((c) => c.added);
  return (
    <DocPage
      crumbs={[{ href: '/', label: 'Overview' }, { label: 'API changelog' }]}
      title="API changelog"
      lede="Changes to the API contracts since October 2024, newest first. Each entry links to the endpoints it touched and the commit that made it."
      head={<div className="feature-links"><a href={CONTRACT_HISTORY}>Contract history on GitHub <Icon name="external" /></a><span className="pill">{changes.length} changes</span><span className="pill">{touched.size} endpoints touched</span>{newEps.length ? <span className="pill pill-teal">{newEps.length} new contracts</span> : null}</div>}
      toc={months.map((m) => ({ id: `m${m}`, text: monthName(m), level: 2 as const }))}
    >
      {!changes.length ? <p className="unavailable">The contract history couldn&apos;t be loaded in this build. <a href={CONTRACT_HISTORY}>See it on GitHub</a>.</p> : null}
      <div className="callout"><Icon name="info" /><p>Built from the git history of the <code className="inline-code">api_contracts</code> folder in the USAspending API repo. Formatting-only and tooling commits are left out. For changes to the website, see the <Link href="/release-notes">release notes</Link>.</p></div>
      {months.map((m) => (
        <section key={m} className="change-group" aria-labelledby={`m${m}`}>
          <h2 id={`m${m}`}>{monthName(m)}</h2>
          {changes.filter((c) => c.date.startsWith(m)).map((c) => {
            const eps = c.endpoints.map(endpoint).filter(Boolean);
            return (
              <div key={c.sha} className="change">
                <time dateTime={c.date}>{formatDate(c.date)}</time>
                <div>
                  <p className="change-summary">
                    {c.added.length ? <span className="pill pill-teal" style={{ marginRight: 6 }}>New</span> : null}
                    {c.removed.length ? <span className="pill pill-accent" style={{ marginRight: 6 }}>Removed</span> : null}
                    {c.summary}
                  </p>
                  <div className="pills">
                    {eps.map((e) => <Link key={e!.id} className="pill pill-mono" href={endpointHref(e!)}>{e!.method} {e!.path}</Link>)}
                    {c.removed.map((r) => <span key={r} className="pill pill-mono">{r}</span>)}
                    {c.touchesGuide ? <Link className="pill" href="/filters">Filter guide</Link> : null}
                    <a className="pill" href={commitUrl(c.sha)}>{c.ticket || c.sha.slice(0, 7)}</a>
                  </div>
                </div>
              </div>
            );
          })}
        </section>
      ))}
    </DocPage>
  );
}

import type { Metadata } from 'next';
import { dictionary, formatDate } from '@/lib/resources';
import { SITE } from '@/lib/docs';
import { DocPage } from '@/components/DocPage';
import { DictionaryTable } from '@/components/DictionaryTable';

export const metadata: Metadata = { title: 'Data dictionary', description: 'Every data element in USAspending downloads and the database, searchable.' };

export default function DataDictionary() {
  const d = dictionary;
  return (
    <DocPage
      wide
      crumbs={[{ href: '/', label: 'Overview' }, { label: 'Data dictionary' }]}
      title="Data dictionary"
      lede="Every data element, its definition, and the column it maps to in award, subaward, and account downloads and in the database. Search it, or open an element to see where it appears."
      head={
        <div className="feature-links">
          <span className="pill pill-mono">GET /api/v2/references/data_dictionary/</span>
          {d.fetchedAt ? <span className="muted">Fetched {formatDate(d.fetchedAt.slice(0, 10))}</span> : null}
          {d.metadata?.download_location ? <a href={d.metadata.download_location}>Download as Excel</a> : null}
        </div>
      }
    >
      {d.rows.length ? <DictionaryTable headers={d.headers} sections={d.sections} rows={d.rows} /> : (
        <p className="unavailable">The data dictionary couldn&apos;t be loaded in this build. It&apos;s also on <a href={`${SITE}/data-dictionary`}>usaspending.gov</a>.</p>
      )}
    </DocPage>
  );
}

import type { Metadata } from 'next';
import { docs } from '@/lib/docs';
import { DocPage } from '@/components/DocPage';
import { Markdown } from '@/components/Markdown';

export const metadata: Metadata = { title: 'The filter object' };

export default function Filters() {
  // Upstream search_filters.md, rendered as-is apart from its own top-level title.
  const md = (docs.filterGuide || '').replace(/^#\s+.*\n/, '');
  return (
    <DocPage
      crumbs={[{ href: '/', label: 'Overview' }, { label: 'The filter object' }]}
      title="The filter object"
      lede="Every search endpoint takes the same filters object. Filters combine with AND; values inside one filter combine with OR."
      head={<p className="muted" style={{ marginTop: 'var(--s-1)', marginBottom: 0 }}>From <a href={`${docs.source.repo}/blob/master/usaspending_api/api_contracts/search_filters.md`}>search_filters.md</a> in the USAspending API repo, updated every build.</p>}
    >
      {md ? <Markdown>{md}</Markdown> : <p className="unavailable">The filter guide couldn&apos;t be loaded in this build.</p>}
    </DocPage>
  );
}

/* Global styles. Colors come only from the --c-* roles in tokens.css, which map to usaspending.gov's own
   USWDS tokens. Spacing follows the USWDS 8px unit scale. */
:root {
  --s-05: 4px; --s-1: 8px; --s-105: 12px; --s-2: 16px; --s-3: 24px; --s-4: 32px; --s-5: 40px; --s-6: 48px; --s-8: 64px;
  --r-sm: 4px; --r-md: 8px; --r-lg: 12px; --r-pill: 999px;
  --topbar: 60px;
  --sidebar: 280px;
  --rail: 224px;
  --measure: 760px;
  --shadow: 0 1px 2px rgb(0 0 0 / 0.06), 0 8px 24px rgb(0 0 0 / 0.08);
}
:root[data-theme='dark'] { --shadow: 0 1px 2px rgb(0 0 0 / 0.4), 0 12px 32px rgb(0 0 0 / 0.45); }

*, *::before, *::after { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; scroll-padding-top: calc(var(--topbar) + var(--s-2)); }
@media (prefers-reduced-motion: no-preference) { html { scroll-behavior: smooth; } }
body {
  margin: 0; background: var(--c-surface); color: var(--c-text);
  font-family: var(--font-sans); font-size: var(--font-size-16); line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
h1, h2, h3, h4 { color: var(--c-text-headline); line-height: 1.2; margin: 0 0 var(--s-105); font-weight: 700; }
h1 { font-size: clamp(var(--font-size-32), 4vw, var(--font-size-40)); letter-spacing: -0.01em; }
h2 { font-size: var(--font-size-24); margin-top: var(--s-6); }
h3 { font-size: var(--font-size-18); margin-top: var(--s-4); }
p { margin: 0 0 var(--s-2); }
a { color: var(--c-action); text-underline-offset: 3px; text-decoration-thickness: 1px; }
a:hover { color: var(--c-action-hover); text-decoration-thickness: 2px; }
code, kbd, pre { font-family: var(--font-mono); }
code { font-size: 0.875em; }
:focus-visible { outline: 3px solid var(--c-focus); outline-offset: 2px; border-radius: 2px; }
.muted { color: var(--c-text-muted); }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
.icon { width: 18px; height: 18px; flex-shrink: 0; }

.skip-link { position: absolute; left: var(--s-2); top: -80px; background: var(--c-action); color: var(--c-on-action); padding: var(--s-1) var(--s-2); z-index: 100; font-weight: 700; border-radius: var(--r-sm); }
.skip-link:focus { top: var(--s-1); }

/* Top bar */
.topbar { position: sticky; top: 0; z-index: 40; height: var(--topbar); display: flex; align-items: center; gap: var(--s-2); padding: 0 var(--s-3); background: var(--c-surface); border-bottom: 1px solid var(--c-border); }
.brand { display: flex; align-items: center; gap: var(--s-105); color: var(--c-text-headline); text-decoration: none; min-height: 44px; white-space: nowrap; }
.brand:hover { color: var(--c-text-headline); text-decoration: none; }
.brand-name { font-size: var(--font-size-18); font-weight: 700; letter-spacing: -0.005em; }
.brand-name span { font-weight: 400; color: var(--c-text-muted); }
.tag { display: inline-flex; align-items: center; font-size: var(--font-size-12); font-weight: 700; line-height: 1; padding: 5px 8px; border-radius: var(--r-pill); background: var(--c-teal-soft); color: var(--c-teal); letter-spacing: 0.02em; }
.search-trigger { margin-left: var(--s-3); flex: 0 1 380px; display: flex; align-items: center; gap: var(--s-1); min-height: 40px; padding: 0 var(--s-105); border: 1px solid var(--c-border); border-radius: var(--r-md); background: var(--c-surface-subtle); color: var(--c-text-muted); font: inherit; font-size: var(--font-size-14); cursor: pointer; text-align: left; }
.search-trigger:hover { border-color: var(--c-border-strong); }
.search-trigger span { flex: 1; }
kbd { font-size: var(--font-size-12); padding: 2px 6px; border: 1px solid var(--c-border); border-bottom-width: 2px; border-radius: var(--r-sm); background: var(--c-surface); color: var(--c-text-muted); }
.topbar-actions { margin-left: auto; display: flex; align-items: center; gap: var(--s-1); }
.icon-button { display: inline-grid; place-items: center; width: 40px; height: 40px; border-radius: var(--r-md); border: 1px solid transparent; background: transparent; color: var(--c-text); cursor: pointer; text-decoration: none; }
.icon-button:hover { background: var(--c-surface-subtle); color: var(--c-text-headline); }
.menu-button { display: none; }
.button { display: inline-flex; align-items: center; justify-content: center; gap: var(--s-1); min-height: 40px; padding: 0 var(--s-2); border-radius: var(--r-md); background: var(--c-action); color: var(--c-on-action); font: inherit; font-size: var(--font-size-14); font-weight: 700; text-decoration: none; border: 1px solid var(--c-action); cursor: pointer; white-space: nowrap; }
.button:hover { background: var(--c-action-hover); border-color: var(--c-action-hover); color: var(--c-on-action); text-decoration: none; }
.button:disabled { background: var(--c-surface-subtle); border-color: var(--c-border); color: var(--c-text-muted); cursor: not-allowed; }
.button-ghost { background: transparent; color: var(--c-text-headline); border-color: var(--c-border); }
.button-ghost:hover { background: var(--c-surface-subtle); color: var(--c-text-headline); border-color: var(--c-border-strong); }
.button-lg { min-height: 48px; padding: 0 var(--s-3); font-size: var(--font-size-16); }

/* Shell */
.shell { display: grid; grid-template-columns: var(--sidebar) minmax(0, 1fr); min-height: calc(100vh - var(--topbar)); }
.sidebar { position: sticky; top: var(--topbar); height: calc(100vh - var(--topbar)); overflow-y: auto; background: var(--c-surface-sidebar); border-right: 1px solid var(--c-border); padding: var(--s-2) var(--s-105) var(--s-6); font-size: var(--font-size-14); overscroll-behavior: contain; }
.nav-group { margin-bottom: var(--s-1); }
.nav-group > summary, .nav-sub > summary { list-style: none; cursor: pointer; display: flex; align-items: center; justify-content: space-between; gap: var(--s-1); border-radius: var(--r-sm); }
.nav-group > summary::-webkit-details-marker, .nav-sub > summary::-webkit-details-marker { display: none; }
.nav-group > summary { padding: var(--s-1) var(--s-1); font-size: var(--font-size-12); font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; color: var(--c-text-muted); min-height: 36px; }
.nav-group > summary:hover, .nav-sub > summary:hover { color: var(--c-text-headline); }
.chev { width: 14px; height: 14px; transition: transform 0.15s; flex-shrink: 0; }
details[open] > summary > .chev { transform: rotate(90deg); }
.nav-list { list-style: none; margin: 0; padding: 0; }
.nav-list a { display: flex; align-items: center; gap: var(--s-1); padding: 6px var(--s-1); min-height: 34px; border-radius: var(--r-sm); color: var(--c-text); text-decoration: none; line-height: 1.3; }
.nav-list a:hover { background: var(--c-surface-subtle); color: var(--c-text-headline); }
.nav-list a[aria-current='page'] { background: var(--c-surface-selected); color: var(--c-text-selected); font-weight: 700; }
.nav-list a .icon { width: 16px; height: 16px; color: var(--c-text-muted); }
.nav-list a[aria-current='page'] .icon { color: var(--c-text-selected); }
.nav-list .count { margin-left: auto; }
.nav-sub { margin: 2px 0; }
.nav-sub > summary { padding: 6px var(--s-1); font-weight: 700; color: var(--c-text-headline); min-height: 34px; }
.nav-sub .nav-list { margin-left: 15px; padding-left: var(--s-1); border-left: 1px solid var(--c-border); }
.count { font-family: var(--font-mono); font-size: 11px; line-height: 1; padding: 3px 6px; border-radius: var(--r-pill); background: var(--c-surface-subtle); color: var(--c-text-muted); }
.scrim { display: none; }

.main { min-width: 0; display: flex; flex-direction: column; }
.doc { flex: 1; display: grid; grid-template-columns: minmax(0, 1fr) var(--rail); gap: var(--s-6); padding: var(--s-5) var(--s-5) var(--s-8); max-width: calc(var(--measure) + var(--rail) + var(--s-6) * 2 + 160px); width: 100%; }
.doc.wide { grid-template-columns: minmax(0, 1fr); max-width: 1200px; }
.doc-body { min-width: 0; }
.doc:not(.wide) .doc-body { max-width: var(--measure); }
.rail { position: sticky; top: calc(var(--topbar) + var(--s-5)); align-self: start; max-height: calc(100vh - var(--topbar) - var(--s-8)); overflow-y: auto; font-size: var(--font-size-14); }
.rail-title { font-size: var(--font-size-12); font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; color: var(--c-text-muted); margin-bottom: var(--s-1); }
.rail ul { list-style: none; margin: 0; padding: 0; border-left: 1px solid var(--c-border); }
.rail a { display: block; padding: 4px var(--s-105); margin-left: -1px; border-left: 2px solid transparent; color: var(--c-text-muted); text-decoration: none; line-height: 1.35; }
.rail a.lvl-3 { padding-left: var(--s-3); font-size: 13px; }
.rail a:hover { color: var(--c-text-headline); }
.rail a.is-active { color: var(--c-action); border-left-color: var(--c-action); font-weight: 700; }
.rail-extra { margin-top: var(--s-3); padding-top: var(--s-2); border-top: 1px solid var(--c-border); display: flex; flex-direction: column; gap: var(--s-1); }
.rail-extra a { color: var(--c-text-muted); text-decoration: none; display: inline-flex; align-items: center; gap: 6px; }
.rail-extra a:hover { color: var(--c-action); }

.crumbs { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; font-size: var(--font-size-14); color: var(--c-text-muted); margin-bottom: var(--s-105); }
.crumbs a { color: var(--c-text-muted); text-decoration: none; }
.crumbs a:hover { color: var(--c-action); text-decoration: underline; }
.lede { font-size: var(--font-size-18); color: var(--c-text); max-width: 680px; }
.page-head { margin-bottom: var(--s-4); padding-bottom: var(--s-3); border-bottom: 1px solid var(--c-border); }
.page-head .lede { margin-bottom: 0; }
.eyebrow { font-size: var(--font-size-12); font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; color: var(--c-teal); margin-bottom: var(--s-1); }

.footer { border-top: 1px solid var(--c-border); padding: var(--s-3) var(--s-5) var(--s-4); font-size: var(--font-size-14); color: var(--c-text-muted); background: var(--c-surface); }
.footer p { max-width: 860px; margin-bottom: var(--s-1); }
.footer a { color: var(--c-text-muted); }
.footer-links { display: flex; gap: var(--s-2); flex-wrap: wrap; }

/* Callouts and cards */
.callout { display: flex; gap: var(--s-105); padding: var(--s-2); border-radius: var(--r-md); background: var(--c-surface-subtle); border: 1px solid var(--c-border); margin: var(--s-3) 0; font-size: var(--font-size-16); }
.callout p:last-child { margin-bottom: 0; }
.callout-accent { background: var(--c-accent-soft); border-color: transparent; border-left: 4px solid var(--c-accent); }
.callout-teal { background: var(--c-teal-soft); border-color: transparent; }
.callout .icon { margin-top: 3px; color: var(--c-teal); }
.cards { display: grid; gap: var(--s-2); grid-template-columns: repeat(auto-fill, minmax(230px, 1fr)); margin: var(--s-3) 0; }
.card { display: flex; flex-direction: column; gap: 6px; padding: var(--s-2) var(--s-3) var(--s-3) var(--s-2); border: 1px solid var(--c-border); border-radius: var(--r-lg); background: var(--c-surface-raised); color: var(--c-text); text-decoration: none; transition: border-color 0.15s, box-shadow 0.15s; }
.card:hover { border-color: var(--c-action); box-shadow: var(--shadow); color: var(--c-text); text-decoration: none; }
.card-icon { width: 36px; height: 36px; display: grid; place-items: center; border-radius: var(--r-md); background: var(--c-surface-selected); color: var(--c-text-selected); margin-bottom: var(--s-05); }
.card-title { font-weight: 700; color: var(--c-text-headline); font-size: var(--font-size-17); line-height: 1.3; display: flex; align-items: center; gap: 6px; }
.card-body { font-size: var(--font-size-14); color: var(--c-text-muted); margin: 0; }

/* Overview */
.hero { padding: var(--s-2) 0 var(--s-4); }
.hero h1 { font-size: clamp(var(--font-size-32), 5vw, var(--font-size-48)); max-width: 760px; }
.hero .lede { font-size: var(--font-size-20); max-width: 720px; }
.hero-actions { display: flex; gap: var(--s-105); flex-wrap: wrap; margin-top: var(--s-3); }
.facts { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); border: 1px solid var(--c-border); border-radius: var(--r-lg); margin: var(--s-3) 0 var(--s-2); overflow: hidden; }
.fact { padding: var(--s-2) var(--s-3); border-right: 1px solid var(--c-border); }
.fact:last-child { border-right: 0; }
.fact strong { display: block; font-size: var(--font-size-24); color: var(--c-text-headline); line-height: 1.2; }
.fact span { font-size: var(--font-size-14); color: var(--c-text-muted); }
.fact code { font-size: var(--font-size-14); color: var(--c-text-headline); }
.menus { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--s-2); margin-top: var(--s-2); }
.menu { border: 1px solid var(--c-border); border-radius: var(--r-lg); padding: var(--s-2) var(--s-3) var(--s-105); background: var(--c-surface-raised); }
.menu h3 { margin: 0 0 4px; font-size: var(--font-size-18); }
.menu > p { font-size: var(--font-size-14); color: var(--c-text-muted); margin-bottom: var(--s-1); }
.menu ul { list-style: none; margin: 0; padding: 0; }
.menu li a { display: flex; align-items: center; gap: var(--s-1); padding: 8px 0; border-top: 1px solid var(--c-border); text-decoration: none; color: var(--c-text); font-size: var(--font-size-16); }
.menu li a:hover { color: var(--c-action); }
.menu li a .icon { color: var(--c-text-muted); width: 16px; height: 16px; }
.menu li a .count { margin-left: auto; }
.two-col { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: var(--s-4); }
.feed { list-style: none; margin: 0; padding: 0; }
.feed li { padding: var(--s-105) 0; border-bottom: 1px solid var(--c-border); }
.feed-meta { display: flex; flex-wrap: wrap; align-items: center; gap: var(--s-1); font-size: var(--font-size-12); color: var(--c-text-muted); margin-bottom: 2px; }
.feed-title { font-weight: 700; color: var(--c-text-headline); text-decoration: none; }
.feed-title:hover { color: var(--c-action); text-decoration: underline; }
.feed p { font-size: var(--font-size-14); margin: 2px 0 0; }
.section-head { display: flex; align-items: baseline; justify-content: space-between; gap: var(--s-2); flex-wrap: wrap; margin-top: var(--s-6); }
.section-head h2 { margin: 0; }
.section-head a { font-size: var(--font-size-14); font-weight: 700; text-decoration: none; }

/* Pills and badges */
.pill { display: inline-flex; align-items: center; gap: 4px; font-size: var(--font-size-12); font-weight: 700; line-height: 1; padding: 4px 8px; border-radius: var(--r-pill); background: var(--c-surface-subtle); color: var(--c-text); text-decoration: none; white-space: nowrap; }
a.pill:hover { background: var(--c-surface-selected); color: var(--c-text-selected); }
.pill-teal { background: var(--c-teal-soft); color: var(--c-teal); }
.pill-accent { background: var(--c-accent-soft); color: var(--c-text-headline); }
.pill-mono { font-family: var(--font-mono); font-weight: 500; white-space: normal; overflow-wrap: anywhere; line-height: 1.3; }
.pills { display: flex; flex-wrap: wrap; gap: 6px; }
.method { display: inline-flex; align-items: center; justify-content: center; font-family: var(--font-mono); font-weight: 700; border-radius: var(--r-sm); flex-shrink: 0; letter-spacing: 0.02em; }
.method-md { font-size: 13px; padding: 4px 10px; }
.method-sm { font-size: 11px; padding: 3px 6px; min-width: 44px; }
.method-get { background: var(--c-get-bg); color: var(--c-get-text); }
.method-post { background: var(--c-post-bg); color: var(--c-post-text); }
.method-counts { display: inline-flex; gap: 6px; }

/* Reference */
.feature-links { display: flex; flex-wrap: wrap; gap: var(--s-1) var(--s-2); align-items: center; margin-top: var(--s-105); font-size: var(--font-size-14); }
.feature-links a { display: inline-flex; align-items: center; gap: 4px; font-weight: 700; text-decoration: none; }
.feature-links a:hover { text-decoration: underline; }
.ep-list { border: 1px solid var(--c-border); border-radius: var(--r-lg); overflow: hidden; margin: var(--s-2) 0 var(--s-4); background: var(--c-surface-raised); }
.ep { border-bottom: 1px solid var(--c-border); }
.ep:last-child { border-bottom: 0; }
.ep > summary { list-style: none; cursor: pointer; display: grid; grid-template-columns: 52px minmax(0, 1fr) auto; align-items: center; gap: var(--s-105); padding: var(--s-105) var(--s-2); min-height: 56px; }
.ep > summary::-webkit-details-marker { display: none; }
.ep > summary:hover { background: var(--c-surface-subtle); }
.ep[open] > summary { background: var(--c-surface-subtle); border-bottom: 1px solid var(--c-border); }
.ep-title { display: flex; flex-direction: column; min-width: 0; }
.ep-title strong { color: var(--c-text-headline); font-size: var(--font-size-16); line-height: 1.3; }
.ep-title code { color: var(--c-text-muted); font-size: 13px; overflow-wrap: anywhere; }
.ep-side { display: flex; align-items: center; gap: var(--s-1); }
.ep-body { padding: var(--s-2) var(--s-3) var(--s-3); }
.ep-body > p { max-width: 720px; }
.ep-facts { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: var(--s-2); }
.ep-actions { display: flex; flex-wrap: wrap; gap: var(--s-1); margin-top: var(--s-2); }
.ref-section { margin-top: var(--s-5); }
.ref-section:first-of-type { margin-top: 0; }
.ref-feature { margin: var(--s-3) 0; }
.ref-feature-head { display: flex; align-items: center; justify-content: space-between; gap: var(--s-2); flex-wrap: wrap; }
.ref-feature-head h3 { margin: 0; }
.ref-feature-head h3 a { color: var(--c-text-headline); text-decoration: none; }
.ref-feature-head h3 a:hover { color: var(--c-action); text-decoration: underline; }
.ref-rows { list-style: none; padding: 0; margin: var(--s-1) 0 0; border-top: 1px solid var(--c-border); }
.ref-rows a { display: grid; grid-template-columns: 52px minmax(0, 1fr) minmax(0, 1.1fr); gap: var(--s-105); align-items: center; padding: 8px var(--s-1); border-bottom: 1px solid var(--c-border); color: var(--c-text-headline); text-decoration: none; font-size: var(--font-size-14); }
.ref-rows a:hover { background: var(--c-surface-subtle); }
.ref-rows code { color: var(--c-text-muted); overflow-wrap: anywhere; font-size: 13px; }
.endpoint-line { display: flex; align-items: center; gap: var(--s-105); flex-wrap: wrap; font-size: var(--font-size-16); padding: var(--s-105) var(--s-2); background: var(--c-surface-subtle); border: 1px solid var(--c-border); border-radius: var(--r-md); margin: var(--s-2) 0; }
.endpoint-line code { overflow-wrap: anywhere; color: var(--c-text-headline); flex: 1; }
.notice { padding: var(--s-105) var(--s-2); border-radius: var(--r-md); background: var(--c-accent-soft); border-left: 4px solid var(--c-accent); color: var(--c-text-headline); margin: var(--s-2) 0; }
.contract-notes { background: var(--c-surface-subtle); border-radius: var(--r-lg); padding: var(--s-05) var(--s-3) var(--s-2); margin-top: var(--s-5); }
.contract-notes h2 { margin-top: var(--s-2); font-size: var(--font-size-18); }
.source-line { margin-top: var(--s-4); font-size: var(--font-size-14); color: var(--c-text-muted); }
.recent { list-style: none; padding: 0; margin: 0; }
.recent li { display: grid; grid-template-columns: 110px minmax(0, 1fr); gap: var(--s-105); padding: 8px 0; border-bottom: 1px solid var(--c-border); font-size: var(--font-size-14); }
.recent time { color: var(--c-text-muted); }

/* Fields */
.fields { list-style: none; margin: var(--s-105) 0 var(--s-3); padding: 0; border-top: 1px solid var(--c-border); }
.fields .fields { margin: var(--s-1) 0 var(--s-1) var(--s-1); border-left: 2px solid var(--c-border); border-top: 0; }
.field { padding: var(--s-105) 0 var(--s-105) var(--s-105); border-bottom: 1px solid var(--c-border); }
.fields .fields .field:last-child { border-bottom: 0; }
.field details > summary { cursor: pointer; list-style: none; display: flex; align-items: center; gap: var(--s-1); flex-wrap: wrap; }
.field details > summary::-webkit-details-marker { display: none; }
.field details > summary::before { content: ''; width: 7px; height: 7px; border-right: 2px solid var(--c-action); border-bottom: 2px solid var(--c-action); transform: rotate(-45deg); margin-right: 2px; transition: transform 0.15s; }
.field details[open] > summary::before { transform: rotate(45deg); }
.field-head { display: inline-flex; align-items: baseline; gap: var(--s-1); flex-wrap: wrap; }
.field-name { font-weight: 700; color: var(--c-text-headline); font-size: var(--font-size-14); }
.field-type { font-family: var(--font-mono); font-size: 12px; color: var(--c-text-muted); }
.field-req { font-size: 12px; font-weight: 700; color: var(--c-danger); }
.field-null { font-size: 12px; color: var(--c-text-muted); }
.field-count { font-size: 12px; color: var(--c-text-muted); }
.field-desc { font-size: var(--font-size-14); margin-top: 2px; }
.field-desc p:last-child { margin-bottom: 0; }
.field-meta { font-size: var(--font-size-14); margin: 4px 0 0; }
.field-meta-label { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; color: var(--c-text-muted); margin-right: 4px; }
.field-meta code, .field-enum code { overflow-wrap: anywhere; }
.field-enum { font-size: var(--font-size-14); margin-top: var(--s-1); }
.field-enum ul { margin: 4px 0 0; padding-left: var(--s-3); columns: 2; column-gap: var(--s-3); }
.field-option { margin-top: var(--s-1); }

/* Code */
.code { margin: var(--s-2) 0; border-radius: var(--r-lg); overflow: hidden; background: var(--c-code-bg); border: 1px solid var(--c-border); }
.code-bar { display: flex; align-items: center; gap: var(--s-05); padding: 0 var(--s-05) 0 var(--s-2); min-height: 44px; font-size: var(--font-size-12); font-weight: 700; color: var(--c-code-muted); border-bottom: 1px solid rgb(255 255 255 / 0.1); }
.code-bar .code-label { flex: 1; letter-spacing: 0.04em; text-transform: uppercase; }
.code-tabs { display: flex; flex: 1; gap: 2px; align-self: stretch; }
.code-tab { background: transparent; border: 0; border-bottom: 2px solid transparent; color: var(--c-code-muted); font: inherit; font-size: var(--font-size-14); font-weight: 700; padding: 0 var(--s-105); cursor: pointer; min-height: 44px; }
.code-tab:hover { color: var(--c-code-text); }
.code-tab[aria-selected='true'] { color: var(--c-code-text); border-bottom-color: var(--c-accent); }
.code-copy { display: inline-flex; align-items: center; gap: 6px; background: transparent; color: var(--c-code-text); border: 1px solid rgb(255 255 255 / 0.2); border-radius: var(--r-sm); font: inherit; font-size: 13px; font-weight: 700; min-height: 32px; padding: 0 var(--s-105); cursor: pointer; }
.code-copy:hover { border-color: var(--c-code-text); }
.code pre, .console pre { margin: 0; padding: var(--s-2); overflow: auto; max-height: 520px; color: var(--c-code-text); font-size: 13px; line-height: 1.6; background: transparent !important; }
.code pre.shiki { background: transparent !important; }
.code pre:focus-visible { outline-offset: -3px; }

/* Console */
.console { margin-top: var(--s-5); border: 1px solid var(--c-border); border-radius: var(--r-lg); overflow: hidden; background: var(--c-surface-raised); }
.console-head { background: var(--c-band); color: var(--c-on-band); padding: var(--s-105) var(--s-3); display: flex; align-items: center; gap: var(--s-2); flex-wrap: wrap; }
.console-head h2 { color: var(--c-on-band); margin: 0; font-size: var(--font-size-18); }
.console-head p { margin: 0; color: var(--c-on-band); opacity: 0.9; font-size: var(--font-size-14); }
.console-inner { padding: 0 var(--s-3) var(--s-3); }
.console-url { display: flex; gap: var(--s-1); align-items: center; margin-top: var(--s-2); padding: var(--s-105); background: var(--c-surface-subtle); border-radius: var(--r-md); }
.console-url code { overflow-wrap: anywhere; color: var(--c-text-headline); }
.console-params { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0 var(--s-2); }
.console-field { display: flex; flex-direction: column; gap: 4px; margin-top: var(--s-2); }
.console-field label { font-size: var(--font-size-14); font-weight: 700; color: var(--c-text-headline); }
.console input, .console select, .console textarea { font: inherit; font-size: 15px; min-height: 44px; padding: var(--s-1) var(--s-105); border: 1px solid var(--c-border-strong); border-radius: var(--r-md); background: var(--c-surface); color: var(--c-text-headline); width: 100%; }
.console textarea { font-family: var(--font-mono); font-size: 13px; line-height: 1.5; resize: vertical; }
.console-actions { display: flex; align-items: center; gap: var(--s-105); margin-top: var(--s-2); flex-wrap: wrap; }
.console-error { color: var(--c-danger); font-weight: 700; }
.console-result { margin-top: var(--s-2); }
.console-status { font-weight: 700; color: var(--c-text-headline); }
.console-status .ok { color: var(--c-get-text); }
.console-status .bad { color: var(--c-danger); }
.console-response { background: var(--c-code-bg); border-radius: var(--r-md); }

/* Prose */
.prose { font-size: var(--font-size-17); }
.prose > :first-child { margin-top: 0; }
.prose h2 { padding-top: var(--s-1); }
.prose ul, .prose ol { padding-left: var(--s-3); margin: 0 0 var(--s-2); }
.prose li { margin-bottom: 4px; }
.prose table { border-collapse: collapse; width: 100%; margin: var(--s-2) 0 var(--s-3); font-size: var(--font-size-14); display: block; overflow-x: auto; }
.prose th, .prose td { text-align: left; padding: var(--s-1) var(--s-105); border-bottom: 1px solid var(--c-border); vertical-align: top; }
.prose th { color: var(--c-text-headline); background: var(--c-surface-subtle); }
.prose pre { background: var(--c-code-bg); color: var(--c-code-text); padding: var(--s-2); border-radius: var(--r-lg); overflow: auto; font-size: 13px; line-height: 1.6; }
.prose :not(pre) > code, .inline-code { background: var(--c-surface-subtle); padding: 1px 5px; border-radius: var(--r-sm); overflow-wrap: anywhere; color: var(--c-text-headline); border: 1px solid var(--c-border); }
.prose hr { border: 0; border-top: 1px solid var(--c-border); margin: var(--s-4) 0; }
.prose blockquote { margin: var(--s-2) 0; padding: var(--s-1) var(--s-2); border-left: 4px solid var(--c-border-strong); color: var(--c-text-muted); }
.prose h2 a, .prose h3 a { color: inherit; }

/* Tables (glossary, dictionary, changelog, guide calls) */
.table-wrap { overflow-x: auto; border: 1px solid var(--c-border); border-radius: var(--r-lg); margin: var(--s-2) 0 var(--s-4); background: var(--c-surface-raised); }
.table { border-collapse: collapse; width: 100%; font-size: var(--font-size-14); }
.table th, .table td { text-align: left; padding: 10px var(--s-2); border-bottom: 1px solid var(--c-border); vertical-align: top; }
.table tr:last-child td { border-bottom: 0; }
.table thead th { position: sticky; top: 0; background: var(--c-surface-subtle); color: var(--c-text-headline); font-size: var(--font-size-12); text-transform: uppercase; letter-spacing: 0.05em; white-space: nowrap; z-index: 1; }
.table td.num { font-family: var(--font-mono); color: var(--c-text-muted); width: 36px; }
.steps { counter-reset: step; list-style: none; padding: 0; margin: var(--s-2) 0 var(--s-4); }
.steps > li { counter-increment: step; position: relative; padding: 0 0 var(--s-3) var(--s-6); border-left: 2px solid var(--c-border); margin-left: 15px; }
.steps > li:last-child { border-left-color: transparent; }
.steps > li::before { content: counter(step); position: absolute; left: -16px; top: -2px; width: 30px; height: 30px; border-radius: 50%; display: grid; place-items: center; background: var(--c-surface-selected); color: var(--c-text-selected); font-size: var(--font-size-14); font-weight: 700; }
.step-when { font-size: var(--font-size-14); color: var(--c-text-muted); margin: 0 0 4px; }
.step-call { display: flex; align-items: center; gap: var(--s-1); flex-wrap: wrap; }
.step-call a { font-weight: 700; }
.step-call code { font-size: 13px; color: var(--c-text-muted); overflow-wrap: anywhere; }
.step-note { font-size: var(--font-size-14); margin: 4px 0 0; }

.filter-bar { display: flex; flex-wrap: wrap; align-items: center; gap: var(--s-105); margin: var(--s-2) 0; }
.filter-bar input, .filter-bar select { font: inherit; font-size: 15px; min-height: 44px; padding: 0 var(--s-105); border: 1px solid var(--c-border-strong); border-radius: var(--r-md); background: var(--c-surface); color: var(--c-text-headline); }
.filter-bar input { flex: 1 1 280px; }
.letters { display: flex; flex-wrap: wrap; gap: 4px; margin: var(--s-1) 0 var(--s-3); }
.letters a { display: grid; place-items: center; min-width: 32px; height: 32px; border-radius: var(--r-sm); background: var(--c-surface-subtle); color: var(--c-text-headline); text-decoration: none; font-weight: 700; font-size: var(--font-size-14); }
.letters a:hover { background: var(--c-surface-selected); color: var(--c-text-selected); }
.terms { margin: 0; }
.term { padding: var(--s-2) 0; border-bottom: 1px solid var(--c-border); }
.term dt { font-weight: 700; color: var(--c-text-headline); font-size: var(--font-size-18); }
.term dd { margin: 4px 0 0; }
.term dd p { margin-bottom: var(--s-1); }
.term-official { font-size: var(--font-size-14); color: var(--c-text-muted); }
.unavailable { padding: var(--s-3); border: 1px dashed var(--c-border-strong); border-radius: var(--r-lg); color: var(--c-text-muted); }

.release { padding: var(--s-3) 0; border-bottom: 1px solid var(--c-border); }
.release-date { margin: 0 0 var(--s-1); font-size: var(--font-size-20); }
.release-date a { color: inherit; text-decoration: none; }
.release-date a:hover { color: var(--c-action); text-decoration: underline; }
.release-section { font-size: var(--font-size-12); text-transform: uppercase; letter-spacing: 0.06em; color: var(--c-text-muted); margin: var(--s-2) 0 var(--s-1); }
.prose.inline p { margin: 0; }
.prose.inline { font-size: inherit; }
.release .prose { font-size: var(--font-size-16); }
.release-api { margin-top: var(--s-2); padding: var(--s-105) var(--s-2); border-radius: var(--r-md); background: var(--c-teal-soft); }
.release-api > p { margin: 0 0 4px; font-size: var(--font-size-14); font-weight: 700; color: var(--c-teal); }
.release-api ul { margin: 0; padding-left: var(--s-3); font-size: var(--font-size-14); }
.year-nav { display: flex; flex-wrap: wrap; gap: 6px; margin: var(--s-2) 0; }
.change-group h2 { font-size: var(--font-size-18); margin-top: var(--s-4); }
.change { display: grid; grid-template-columns: 110px minmax(0, 1fr); gap: var(--s-2); padding: var(--s-105) 0; border-bottom: 1px solid var(--c-border); }
.change time { font-size: var(--font-size-14); color: var(--c-text-muted); }
.change-summary { margin: 0 0 6px; color: var(--c-text-headline); }
.change .pills a { text-decoration: none; }

/* Search dialog */
.search-dialog { width: min(640px, calc(100vw - 32px)); max-height: min(560px, calc(100vh - 96px)); margin: 72px auto auto; padding: 0; border: 1px solid var(--c-border); border-radius: var(--r-lg); background: var(--c-surface-raised); color: var(--c-text); box-shadow: var(--shadow); overflow: hidden; }
.search-dialog[open] { display: flex; flex-direction: column; }
.search-dialog::backdrop { background: rgb(0 0 0 / 0.45); }
.search-box { display: flex; align-items: center; gap: var(--s-1); padding: 0 var(--s-2); border-bottom: 1px solid var(--c-border); }
.search-box .icon { color: var(--c-text-muted); }
.search-box input { flex: 1; min-height: 56px; border: 0; background: transparent; color: var(--c-text-headline); font: inherit; font-size: var(--font-size-18); outline: none; }
.search-results { list-style: none; margin: 0; padding: var(--s-1); overflow-y: auto; }
.search-results a { display: flex; align-items: center; gap: var(--s-105); padding: var(--s-1) var(--s-105); border-radius: var(--r-md); color: var(--c-text); text-decoration: none; }
.search-results a[aria-selected='true'], .search-results a:hover { background: var(--c-surface-selected); color: var(--c-text-selected); }
.search-results .r-main { display: flex; flex-direction: column; min-width: 0; flex: 1; }
.search-results .r-title { font-weight: 700; color: inherit; }
.search-results .r-sub { font-size: 13px; color: var(--c-text-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.search-results .r-kind { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; color: var(--c-text-muted); }
.search-empty { padding: var(--s-3); color: var(--c-text-muted); text-align: center; }
.search-foot { display: flex; gap: var(--s-2); padding: var(--s-1) var(--s-2); border-top: 1px solid var(--c-border); font-size: 12px; color: var(--c-text-muted); }

/* Responsive */
@media (max-width: 1200px) {
  .doc { grid-template-columns: minmax(0, 1fr); }
  .rail { display: none; }
}
@media (max-width: 960px) {
  .shell { grid-template-columns: minmax(0, 1fr); }
  .menu-button { display: inline-grid; }
  .sidebar { position: fixed; top: var(--topbar); left: 0; bottom: 0; width: min(320px, 86vw); height: auto; z-index: 35; transform: translateX(-100%); transition: transform 0.2s; box-shadow: var(--shadow); visibility: hidden; }
  .sidebar.is-open { transform: none; visibility: visible; }
  .scrim.is-open { display: block; position: fixed; inset: var(--topbar) 0 0 0; background: rgb(0 0 0 / 0.4); z-index: 30; border: 0; padding: 0; }
  .search-trigger { margin-left: auto; flex: 0 0 auto; }
  .search-trigger span, .search-trigger kbd { display: none; }
  .topbar-actions { margin-left: 0; }
  .two-col, .menus { grid-template-columns: minmax(0, 1fr); }
  .facts { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .fact:nth-child(2) { border-right: 0; }
  .fact:nth-child(-n+2) { border-bottom: 1px solid var(--c-border); }
}
@media (max-width: 640px) {
  .topbar { padding: 0 var(--s-2); gap: var(--s-1); }
  .brand-name span, .try-button, .gh-link { display: none; }
  .brand { gap: var(--s-1); }
  .brand-name { font-size: var(--font-size-16); }
  .topbar .tag { font-size: 11px; padding: 4px 6px; }
  .doc { padding: var(--s-3) var(--s-2) var(--s-6); }
  .footer { padding: var(--s-3) var(--s-2); }
  .console-params { grid-template-columns: minmax(0, 1fr); }
  .console-inner { padding: 0 var(--s-2) var(--s-2); }
  .ep > summary { grid-template-columns: 48px minmax(0, 1fr); padding: var(--s-105); }
  .ep-side { display: none; }
  .ep-body { padding: var(--s-2); }
  .ref-rows a { grid-template-columns: 48px minmax(0, 1fr); }
  .ref-rows a code { grid-column: 2; }
  .field-enum ul { columns: 1; }
  .change, .recent li { grid-template-columns: minmax(0, 1fr); gap: 2px; }
}
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition: none !important; } }

import type { Metadata } from 'next';
import { glossary, formatDate } from '@/lib/resources';
