export default function ReleaseNotes() {
  const years = [...new Set(releases.map((r) => r.date.slice(0, 4)))];
  const apiCount = releases.filter((r) => r.apiItems.length).length;
  return (
    <DocPage
      crumbs={[{ href: '/', label: 'Overview' }, { label: 'Release notes' }]}
