import { Icon } from './Icon';

function CopyButton({ code }: { code: string }) {
  const [copied, setCopied] = useState(false);
  async function copy() {
    try { await navigator.clipboard.writeText(code); setCopied(true); setTimeout(() => setCopied(false), 1600); } catch { setCopied(false); }
  }
  return (
    <button type="button" className="code-copy" onClick={copy} aria-live="polite">
      <Icon name={copied ? 'check' : 'copy'} className="icon" />{copied ? 'Copied' : 'Copy'}
    </button>
  );
}

export function CodeFrame({ code, html, label }: { code: string; html: string; label: string }) {
  return (
    <figure className="code">
      <figcaption className="code-bar"><span className="code-label">{label}</span><CopyButton code={code} /></figcaption>
      <div dangerouslySetInnerHTML={{ __html: html }} />
    </figure>
  );
}

// Language tabs. The chosen language is remembered and shared by every tab set on the page.
const EVT = 'codetabs:change';
export function CodeTabsClient({ tabs, group }: { tabs: { label: string; lang: string; code: string; html: string }[]; group: string }) {
  const id = useId();
  const [sel, setSel] = useState(0);
  useEffect(() => {
    const pick = (label: string | null) => { const i = tabs.findIndex((t) => t.label === label); if (i >= 0) setSel(i); };
    try { pick(localStorage.getItem(`tabs:${group}`)); } catch { /* storage unavailable */ }
    const on = (e: Event) => { const d = (e as CustomEvent).detail; if (d.group === group) pick(d.label); };
    window.addEventListener(EVT, on);
    return () => window.removeEventListener(EVT, on);
  }, [tabs, group]);
  function choose(i: number) {
    setSel(i);
    try { localStorage.setItem(`tabs:${group}`, tabs[i].label); } catch { /* storage unavailable */ }
    window.dispatchEvent(new CustomEvent(EVT, { detail: { group, label: tabs[i].label } }));
  }
  function onKey(e: React.KeyboardEvent, i: number) {
    let n = i;
    if (e.key === 'ArrowRight') n = (i + 1) % tabs.length;
    else if (e.key === 'ArrowLeft') n = (i - 1 + tabs.length) % tabs.length;
    else return;
    e.preventDefault();
    choose(n);
    document.getElementById(`${id}-tab-${n}`)?.focus();
  }
  const t = tabs[sel];
  return (
    <figure className="code">
      <figcaption className="code-bar">
        <div className="code-tabs" role="tablist" aria-label="Language">
          {tabs.map((x, i) => (
            <button key={x.label} id={`${id}-tab-${i}`} type="button" role="tab" className="code-tab" aria-selected={i === sel} aria-controls={`${id}-panel`} tabIndex={i === sel ? 0 : -1} onClick={() => choose(i)} onKeyDown={(e) => onKey(e, i)}>
              {x.label}
            </button>
          ))}
        </div>
        <CopyButton code={t.code} />
      </figcaption>
      <div id={`${id}-panel`} role="tabpanel" aria-labelledby={`${id}-tab-${sel}`} dangerouslySetInnerHTML={{ __html: t.html }} />
    </figure>
  );
}

'use client';
import { useMemo, useState } from 'react';

type Param = { name?: string; in?: 'path' | 'query'; required?: boolean; example?: unknown; default?: unknown; enum?: { value: unknown }[]; type: string };

const API = 'https://api.usaspending.gov';

function initial(p: Param) {
  const v = p.example ?? (p.in === 'path' ? '' : undefined);
  return v === undefined || v === null ? '' : typeof v === 'string' ? v : JSON.stringify(v);
}

export function Console({ method, path, params = [], requestExample, compact: small }: { method: string; path: string; params?: Param[]; requestExample?: string; compact?: boolean }) {
  const [values, setValues] = useState<Record<string, string>>(() => Object.fromEntries(params.map((p) => [p.name || '', initial(p)])));
  const [body, setBody] = useState(requestExample || '{}');
  const [state, setState] = useState<{ status?: number; ms?: number; text?: string; error?: string; loading?: boolean; truncated?: boolean }>({});

  const built = useMemo(() => {
    let p = path;
    const q = new URLSearchParams();
    for (const prm of params) {
      const v = values[prm.name || '']?.trim();
      if (prm.in === 'path') p = p.replace(`{${prm.name}}`, v ? encodeURIComponent(v) : `{${prm.name}}`);
      else if (v) q.set(prm.name || '', v);
    }
    const qs = q.toString();
    return { path: p, url: `${p}${qs ? `?${qs}` : ''}`, missing: /\{[^}]+\}/.test(p) };
  }, [path, params, values]);

  let bodyError: string | null = null;
  if (method === 'POST') {
    try { JSON.parse(body); } catch { bodyError = 'The request body isn’t valid JSON yet.'; }
  }


  async function send() {
    setState({ loading: true });
    const started = performance.now();
    try {
      const res = await fetch(`/api/proxy${built.url.replace(/^\/api/, '')}`, {
        method,
        headers: { 'content-type': 'application/json' },
        body: method === 'POST' ? body : undefined,
      });
      const text = await res.text();
      let pretty = text;
      try { pretty = JSON.stringify(JSON.parse(text), null, 2); } catch { /* not JSON */ }
      const cap = 200_000;
      setState({ status: res.status, ms: Math.round(performance.now() - started), text: pretty.length > cap ? `${pretty.slice(0, cap)}\n…` : pretty, truncated: pretty.length > cap || res.headers.get('x-truncated') === 'true' });
    } catch {
      setState({ error: 'The request didn’t complete. Check your connection and try again.' });
    }
  }

  return (
    <section className="console" aria-labelledby="try-it" data-toc-skip={small ? true : undefined}>
      <div className="console-head">
        <h2 id="try-it">Try it</h2>
        <p>Runs against the live API. Responses are real data.</p>
      </div>
      <div className="console-inner">
      <div className="console-url"><span className={`method method-${method.toLowerCase()} method-sm`}>{method}</span><code>{built.url}</code></div>
      {params.length ? (
        <div className="console-params">
          {params.map((p) => {
            const id = `param-${p.name}`;
            return (
              <div key={p.name} className="console-field">
                <label htmlFor={id}>
                  <code>{p.name}</code> <span className="muted">{p.in}{p.required ? ', required' : ''}</span>
                </label>
                {p.enum?.length ? (
                  <select id={id} value={values[p.name || ''] ?? ''} onChange={(e) => setValues({ ...values, [p.name || '']: e.target.value })}>
                    <option value="">{p.required ? 'Choose a value' : 'Not set'}</option>
                    {p.enum.map((o) => <option key={String(o.value)} value={String(o.value)}>{String(o.value)}</option>)}
                  </select>
                ) : (
                  <input id={id} type="text" value={values[p.name || ''] ?? ''} onChange={(e) => setValues({ ...values, [p.name || '']: e.target.value })} placeholder={p.default !== undefined ? `Default: ${String(p.default)}` : undefined} />
                )}
              </div>
            );
          })}
        </div>
      ) : null}
      {method === 'POST' ? (
        <div className="console-field">
          <label htmlFor="console-body">Request body</label>
          <textarea id="console-body" spellCheck={false} value={body} onChange={(e) => setBody(e.target.value)} rows={Math.min(18, Math.max(6, body.split('\n').length + 1))} aria-describedby={bodyError ? 'console-body-error' : undefined} />
          {bodyError ? <p id="console-body-error" className="console-error">{bodyError}</p> : null}
        </div>
      ) : null}
      <div className="console-actions">
        <button type="button" className="button button-lg" onClick={send} disabled={state.loading || !!bodyError || built.missing}>
          {state.loading ? 'Sending…' : 'Send request'}
        </button>
        {built.missing ? <span className="muted">Fill in the path parameters first.</span> : null}
      </div>
      <div aria-live="polite">
        {state.error ? <p className="console-error">{state.error}</p> : null}
        {state.status !== undefined ? (
          <div className="console-result">
            <p className="console-status">
              <span className={state.status < 400 ? 'ok' : 'bad'}>{state.status}</span> in {state.ms} ms
              {state.truncated ? <span className="muted"> · showing the first part of a large response</span> : null}
            </p>
            <pre tabIndex={0} className="console-response" aria-label="Response body"><code>{state.text}</code></pre>
          </div>
        ) : null}
      </div>
      </div>
    </section>
  );
}

'use client';
import { useMemo, useState } from 'react';

type Props = { headers: { raw: string; display: string }[]; sections: { section: string; colspan: number }[]; rows: (string | null)[][] };

// Searchable data dictionary. Each element opens to show where it appears in downloads,
// the database, and legacy files, grouped by the dictionary's own column sections.
export function DictionaryTable({ headers, sections, rows }: Props) {
  const [q, setQ] = useState('');
  const [group, setGroup] = useState('');
  const [limit, setLimit] = useState(60);
  const col = (raw: string) => headers.findIndex((h) => h.raw === raw);
  const iEl = Math.max(0, col('element'));
  const iDef = col('definition');
  const iGroup = col('grouping');
  const sectionOf = useMemo(() => {
    const out: string[] = [];
    for (const s of sections) for (let i = 0; i < s.colspan; i++) out.push(s.section);
    return out;
  }, [sections]);
  const groups = useMemo(() => (iGroup < 0 ? [] : [...new Set(rows.map((r) => r[iGroup]).filter(Boolean) as string[])].sort()), [rows, iGroup]);
  const filtered = useMemo(() => {
    const w = q.toLowerCase().trim();
    return rows.filter((r) => (!group || r[iGroup] === group) && (!w || r.some((c) => c && c.toLowerCase().includes(w))));
  }, [rows, q, group, iGroup]);

  return (
    <div>
      <div className="filter-bar">
        <label className="sr-only" htmlFor="dd-q">Search the data dictionary</label>
        <input id="dd-q" type="search" placeholder="Search elements, definitions, file columns" value={q} onChange={(e) => { setQ(e.target.value); setLimit(60); }} />
        {groups.length ? (
          <>
            <label className="sr-only" htmlFor="dd-g">Grouping</label>
            <select id="dd-g" value={group} onChange={(e) => { setGroup(e.target.value); setLimit(60); }}>
              <option value="">All groupings</option>
              {groups.map((g) => <option key={g} value={g}>{g}</option>)}
            </select>
          </>
        ) : null}
        <span className="muted" aria-live="polite">{filtered.length} of {rows.length} elements</span>
      </div>
      <div className="ep-list">
        {filtered.slice(0, limit).map((r, n) => (
          <details key={`${r[iEl]}-${n}`} className="ep">
            <summary style={{ gridTemplateColumns: 'minmax(0, 1fr) auto' }}>
              <span className="ep-title"><strong>{r[iEl]}</strong>{iDef >= 0 && r[iDef] ? <span className="muted" style={{ fontSize: 'var(--font-size-14)' }}>{(r[iDef] || '').slice(0, 140)}{(r[iDef] || '').length > 140 ? '…' : ''}</span> : null}</span>
              <span className="ep-side">{iGroup >= 0 && r[iGroup] ? <span className="pill">{r[iGroup]}</span> : null}</span>
            </summary>
            <div className="ep-body">
              {iDef >= 0 && r[iDef] ? <p style={{ whiteSpace: 'pre-line' }}>{r[iDef]}</p> : null}
              <div className="table-wrap">
                <table className="table">
                  <tbody>
                    {headers.map((h, i) => (i === iEl || i === iDef || !r[i] ? null : (
                      <tr key={h.raw}>
                        <th scope="row" style={{ width: '38%' }}><span className="muted" style={{ fontWeight: 400 }}>{sectionOf[i] ? `${sectionOf[i]} · ` : ''}</span>{h.display}</th>
                        <td style={{ whiteSpace: 'pre-line', overflowWrap: 'anywhere' }}>{r[i]}</td>
                      </tr>
                    )))}
                  </tbody>
                </table>
              </div>
            </div>
          </details>
        ))}
      </div>
      {filtered.length > limit ? <button type="button" className="button button-ghost" onClick={() => setLimit(limit + 100)}>Show {Math.min(100, filtered.length - limit)} more</button> : null}
    </div>
  );
}

import Link from 'next/link';
import { OnThisPage, type TocItem } from './OnThisPage';

export type Crumb = { href?: string; label: string };

// The standard page frame: breadcrumbs, title, lede, body, and the on-this-page rail.
export function DocPage({
  crumbs, eyebrow, title, lede, head, children, toc, rail, wide,
}: {
  crumbs?: Crumb[]; eyebrow?: string; title: React.ReactNode; lede?: React.ReactNode; head?: React.ReactNode;
  children: React.ReactNode; toc?: TocItem[]; rail?: React.ReactNode; wide?: boolean;
}) {
  return (
    <div className={`doc${wide ? ' wide' : ''}`}>
      <article className="doc-body" id="content" tabIndex={-1}>
        <header className="page-head">
          {crumbs?.length ? (
            <nav aria-label="Breadcrumb" className="crumbs">
              {crumbs.map((c, i) => (
                <span key={i} style={{ display: 'contents' }}>
                  {i ? <span aria-hidden="true">/</span> : null}
                  {c.href ? <Link href={c.href}>{c.label}</Link> : <span aria-current="page">{c.label}</span>}
                </span>
              ))}
            </nav>
          ) : null}
          {eyebrow ? <p className="eyebrow">{eyebrow}</p> : null}
          <h1>{title}</h1>
          {lede ? <p className="lede">{lede}</p> : null}
          {head}
        </header>
        {children}
      </article>
      {wide ? null : <OnThisPage items={toc}>{rail}</OnThisPage>}
    </div>
  );
}

import Link from 'next/link';
import type { Endpoint } from '@/lib/docs';
import { endpointHref, firstSentence } from '@/lib/docs';
import { samples } from '@/lib/samples';
import { MethodBadge } from './MethodBadge';
import { CodeTabs } from './Code';
import { Icon } from './Icon';

// One endpoint as an accordion row: the summary line always shows; details, parameters,
// and request samples open in place. The row id makes /reference/<feature>#<endpoint> links work.
export function EndpointRow({ e }: { e: Endpoint }) {
  const params = e.params || [];
  const bodyFields = e.request?.fields?.map((f) => f.name).filter(Boolean) as string[] | undefined;
  const text = e.description || e.summary || '';
  return (
    <details className="ep" id={e.id}>
      <summary>
        <MethodBadge method={e.method} size="sm" />
        <span className="ep-title"><strong>{e.title}</strong><code>{e.path}</code></span>
        <span className="ep-side">
          {e.status === 'in-development' ? <span className="pill pill-accent">In development</span> : null}
          {e.status === 'deprecated' ? <span className="pill pill-accent">Deprecated</span> : null}
          <Icon name="chevron" className="chev" />
        </span>
      </summary>
      <div className="ep-body">
        {text ? <p>{firstSentence(text)}</p> : null}
        {params.length || bodyFields?.length ? (
          <div className="ep-facts">
            {params.map((p) => <span key={p.name} className="pill pill-mono" title={`${p.in} parameter`}>{p.in === 'path' ? `{${p.name}}` : `?${p.name}`}{p.required ? ' *' : ''}</span>)}
            {bodyFields?.slice(0, 10).map((n) => <span key={n} className="pill pill-mono" title="Request body field">{n}</span>)}
            {bodyFields && bodyFields.length > 10 ? <span className="pill">+{bodyFields.length - 10} more</span> : null}
          </div>
        ) : null}
        <CodeTabs tabs={samples(e)} />
        <div className="ep-actions">
          <Link href={endpointHref(e)} className="button">Full reference and live console <Icon name="arrow" /></Link>
          <a href={e.source.url} className="button button-ghost"><Icon name="github" />Contract</a>
        </div>
      </div>
    </details>
  );
}

import type { Field } from '@/lib/docs';
import { Markdown } from './Markdown';

function typeLabel(f: Field): string {
  if (f.type === 'array') return f.items ? `array of ${f.items.ref || typeLabel(f.items)}` : 'array';
  if (f.type === 'enum') return `enum${f.valueType ? ` (${f.valueType})` : ''}`;
  if (f.type === 'oneOf') return 'one of';
  return f.ref && !['object', 'array', 'enum'].includes(f.type) ? f.ref : f.ref ? `${f.type} · ${f.ref}` : f.type;
}

function childrenOf(f: Field): Field[] | undefined {
  if (f.fields?.length) return f.fields;
  if (f.type === 'array' && f.items?.fields?.length) return f.items.fields;
  return undefined;
}

function show(v: unknown) {
  return typeof v === 'string' ? v : JSON.stringify(v);
}

function Row({ f, depth }: { f: Field; depth: number }) {
  const kids = childrenOf(f);
  const enumVals = f.enum || (f.type === 'array' ? f.items?.enum : undefined);
  const refDesc = f.refDescription || (f.type === 'array' ? f.items?.refDescription : undefined);
  const body = (
    <>
      {f.description ? <Markdown className="field-desc">{f.description}</Markdown> : null}
      {!f.description && refDesc ? <Markdown className="field-desc">{refDesc}</Markdown> : null}
      {enumVals?.length ? (
        <div className="field-enum">
          <span className="field-meta-label">Allowed values</span>
          <ul>
            {enumVals.slice(0, 60).map((v, i) => (
              <li key={i}><code>{show(v.value)}</code>{v.description ? <span> {v.description}</span> : null}</li>
            ))}
            {enumVals.length > 60 ? <li>and {enumVals.length - 60} more in the source contract</li> : null}
          </ul>
        </div>
      ) : null}
      {f.default !== undefined ? <p className="field-meta"><span className="field-meta-label">Default</span> <code>{show(f.default)}</code></p> : null}
      {f.example !== undefined && f.type !== 'object' ? <p className="field-meta"><span className="field-meta-label">Example</span> <code>{show(f.example)}</code></p> : null}
      {f.options?.length ? (
        <div className="field-oneof">
          {f.options.map((o, i) => (
            <div key={i} className="field-option">
              <span className="field-meta-label">Option {i + 1}</span>
              <FieldList fields={o.fields} depth={depth + 1} />
            </div>
          ))}
        </div>
      ) : null}
    </>
  );
  const head = (
    <span className="field-head">
      <code className="field-name">{f.name}</code>
      <span className="field-type">{typeLabel(f)}</span>
      {f.required ? <span className="field-req">Required</span> : null}
      {f.nullable ? <span className="field-null">Nullable</span> : null}
    </span>
  );
  if (kids) {
    return (
      <li className="field">
        <details open={depth === 0 && kids.length <= 12}>
          <summary>{head}<span className="field-count">{kids.length} {kids.length === 1 ? 'field' : 'fields'}</span></summary>
          {body}
          <FieldList fields={kids} depth={depth + 1} />
        </details>
      </li>
    );
  }
  return (
    <li className="field">
      {head}
      {body}
    </li>
  );
}

export function FieldList({ fields, depth = 0 }: { fields: Field[]; depth?: number }) {
  if (!fields.length) return <p className="muted">No fields are documented for this object.</p>;
  return (
    <ul className={`fields depth-${Math.min(depth, 4)}`}>
      {fields.map((f, i) => <Row key={`${f.name}-${i}`} f={f} depth={depth} />)}
    </ul>
  );
}

export function Schema({ field }: { field?: Field }) {
  if (!field) return <p className="muted">The contract doesn&apos;t describe this body.</p>;
  const kids = childrenOf(field);
  if (kids) return <FieldList fields={kids} />;
  return <FieldList fields={[{ ...field, name: '(body)' }]} />;
}

'use client';
import { useEffect } from 'react';

// Opens the accordion row named in the URL hash, so shared links land on an open row.
export function HashOpener() {
  useEffect(() => {
    function open() {
      const id = decodeURIComponent(window.location.hash.slice(1));
      if (!id) return;
      const el = document.getElementById(id);
      if (el instanceof HTMLDetailsElement) { el.open = true; el.scrollIntoView({ block: 'start' }); }
    }
    open();
    window.addEventListener('hashchange', open);
    return () => window.removeEventListener('hashchange', open);
  }, []);
  return null;
}

import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import rehypeSlug from 'rehype-slug';
import { Code } from './Code';

type HastNode = { type: string; value?: string; tagName?: string; properties?: { className?: string[] }; children?: HastNode[] };
const text = (n?: HastNode): string => (!n ? '' : n.type === 'text' ? n.value || '' : (n.children || []).map(text).join(''));

// Renders contract prose and hand-written content. Fenced code gets the same highlighting as the rest of the site.
export function Markdown({ children, className }: { children?: string; className?: string }) {
  if (!children) return null;
  return (
    <div className={className ? `prose ${className}` : 'prose'}>
      <ReactMarkdown
        remarkPlugins={[remarkGfm]}
        rehypePlugins={[rehypeSlug]}
        components={{
          pre({ node }) {
            const codeEl = (node as unknown as HastNode)?.children?.find((c) => c.tagName === 'code');
            const cls = codeEl?.properties?.className?.find((c) => c.startsWith('language-'));
            const lang = cls ? cls.replace('language-', '') : 'text';
            return <Code code={text(codeEl).replace(/\n$/, '')} lang={lang === 'sh' || lang === 'shell' ? 'bash' : lang === 'js' ? 'javascript' : lang} />;
          },
        }}
      >
        {children}
      </ReactMarkdown>
    </div>
  );
}

export function MethodBadge({ method, size = 'md' }: { method: string; size?: 'sm' | 'md' }) {
  return <span className={`method method-${method.toLowerCase()} method-${size}`}>{method}</span>;
}

'use client';
import { usePathname } from 'next/navigation';
import { useEffect, useState } from 'react';

export type TocItem = { id: string; text: string; level: 2 | 3 };

// Lists the page's headings (or the items passed in) and highlights the one being read.
export function OnThisPage({ items: given, children }: { items?: TocItem[]; children?: React.ReactNode }) {
  const pathname = usePathname();
  const [items, setItems] = useState<TocItem[]>(given || []);
  const [active, setActive] = useState<string | null>(null);

  useEffect(() => {
    if (given) { setItems(given); return; }
    const root = document.querySelector('.doc-body');
    if (!root) return;
    const hs = Array.from(root.querySelectorAll<HTMLElement>('h2[id], h3[id]')).filter((h) => !h.closest('[data-toc-skip]'));
    setItems(hs.map((h) => ({ id: h.id, text: h.textContent || '', level: h.tagName === 'H3' ? 3 : 2 })));
  }, [given, pathname]);

  useEffect(() => {
    if (!items.length) return;
    const els = items.map((i) => document.getElementById(i.id)).filter(Boolean) as HTMLElement[];
    const obs = new IntersectionObserver(
      (entries) => {
        const visible = entries.filter((e) => e.isIntersecting).sort((a, b) => a.boundingClientRect.top - b.boundingClientRect.top);
        if (visible[0]) setActive(visible[0].target.id);
      },
      { rootMargin: '-72px 0px -65% 0px', threshold: 0 },
    );
    els.forEach((el) => obs.observe(el));
    return () => obs.disconnect();
  }, [items]);

  if (!items.length && !children) return <aside className="rail" aria-hidden="true" />;
  return (
    <aside className="rail" aria-label="On this page">
      {items.length ? (
        <>
          <p className="rail-title">On this page</p>
          <ul>
            {items.map((i) => (
              <li key={i.id}>
                <a href={`#${i.id}`} className={`lvl-${i.level}${active === i.id ? ' is-active' : ''}`} aria-current={active === i.id ? 'location' : undefined}
                  onClick={() => { const el = document.getElementById(i.id); if (el instanceof HTMLDetailsElement) el.open = true; }}>
                  {i.text}
                </a>
              </li>
            ))}
          </ul>
        </>
      ) : null}
      {children ? <div className="rail-extra">{children}</div> : null}
    </aside>
  );
}

'use client';
import { useRouter } from 'next/navigation';
import { useEffect, useMemo, useRef, useState } from 'react';
import { Icon } from './Icon';

type Entry = { t: string; s: string; h: string; k: string; m?: string; x?: string };

const KIND_ICON: Record<string, string> = { Endpoint: 'code', Feature: 'layers', Guide: 'guide', Page: 'file', Term: 'book', Release: 'megaphone' };

function score(e: Entry, words: string[]) {
  const title = e.t.toLowerCase();
  const hay = `${title} ${e.s.toLowerCase()} ${(e.x || '').toLowerCase()}`;
  let total = 0;
  for (const w of words) {
    if (!hay.includes(w)) return 0;
    if (title.startsWith(w)) total += 6;
    else if (title.includes(w)) total += 4;
    else if (e.s.toLowerCase().includes(w)) total += 2;
    else total += 1;
  }
  if (e.k === 'Feature' || e.k === 'Guide') total += 1;
  return total;
}

export function SearchDialog({ open, onClose }: { open: boolean; onClose: () => void }) {
  const ref = useRef<HTMLDialogElement>(null);
  const input = useRef<HTMLInputElement>(null);
  const router = useRouter();
  const [index, setIndex] = useState<Entry[] | null>(null);
  const [failed, setFailed] = useState(false);
  const [q, setQ] = useState('');
  const [sel, setSel] = useState(0);

  useEffect(() => {
    const d = ref.current;
    if (!d) return;
    if (open && !d.open) {
      d.showModal();
      setTimeout(() => input.current?.focus(), 0);
      if (!index) fetch('/search-index.json').then((r) => r.json()).then(setIndex).catch(() => setFailed(true));
    } else if (!open && d.open) d.close();
  }, [open, index]);

  const results = useMemo(() => {
    if (!index) return [];
    const words = q.toLowerCase().trim().split(/\s+/).filter(Boolean);
    if (!words.length) return index.filter((e) => e.k === 'Guide' || e.k === 'Page').slice(0, 10);
    return index.map((e) => ({ e, s: score(e, words) })).filter((r) => r.s > 0).sort((a, b) => b.s - a.s).slice(0, 30).map((r) => r.e);
  }, [index, q]);

  useEffect(() => { setSel(0); }, [q]);

  function go(e?: Entry) {
    if (!e) return;
    onClose();
    setQ('');
    if (e.h.startsWith('http')) window.location.href = e.h;
    else router.push(e.h);
  }
  function onKey(ev: React.KeyboardEvent) {
    if (ev.key === 'ArrowDown') { ev.preventDefault(); setSel((s) => Math.min(s + 1, results.length - 1)); }
    else if (ev.key === 'ArrowUp') { ev.preventDefault(); setSel((s) => Math.max(s - 1, 0)); }
    else if (ev.key === 'Enter') { ev.preventDefault(); go(results[sel]); }
  }
  useEffect(() => {
    document.getElementById(`sr-${sel}`)?.scrollIntoView({ block: 'nearest' });
  }, [sel]);

  return (
    <dialog ref={ref} className="search-dialog" aria-label="Search the docs" onClose={onClose} onClick={(e) => { if (e.target === ref.current) onClose(); }}>
      <div className="search-box">
        <Icon name="search" />
        <input
          ref={input}
          type="text"
          value={q}
          onChange={(e) => setQ(e.target.value)}
          onKeyDown={onKey}
          placeholder="Search endpoints, paths, guides, glossary terms"
          aria-label="Search"
          role="combobox"
          aria-expanded="true"
          aria-controls="search-results"
          aria-activedescendant={results.length ? `sr-${sel}` : undefined}
          autoComplete="off"
          spellCheck={false}
        />
        <button type="button" className="icon-button" onClick={onClose} aria-label="Close search"><Icon name="close" /></button>
      </div>
      {failed ? <p className="search-empty">Search couldn&apos;t load. Try again in a moment.</p> : !index ? <p className="search-empty">Loading…</p> : results.length ? (
        <ul className="search-results" id="search-results" role="listbox">
          {results.map((e, i) => (
            <li key={`${e.h}-${i}`} role="presentation">
              <a id={`sr-${i}`} href={e.h} role="option" aria-selected={i === sel} onClick={(ev) => { ev.preventDefault(); go(e); }} onMouseMove={() => setSel(i)}>
                {e.m ? <span className={`method method-sm method-${e.m.toLowerCase()}`}>{e.m}</span> : <Icon name={KIND_ICON[e.k] || 'dot'} />}
                <span className="r-main"><span className="r-title">{e.t}</span><span className="r-sub">{e.s}</span></span>
                <span className="r-kind">{e.k}</span>
              </a>
            </li>
          ))}
        </ul>
      ) : <p className="search-empty">No matches for “{q}”.</p>}
      <div className="search-foot" aria-hidden="true"><span><kbd>↑</kbd> <kbd>↓</kbd> to move</span><span><kbd>Enter</kbd> to open</span><span><kbd>Esc</kbd> to close</span></div>
    </dialog>
  );
}

